<script setup lang="ts">
import {ref,computed,onMounted} from 'vue';import AdminDialog from '../../AdminDialog.vue';
const props=defineProps<{openId?:number;csrf?:string}>(),emit=defineEmits(['notice','changed']);
const data=ref<any>(null),form=ref<any>(null),busy=ref(false),error=ref(''),search=ref('');
const readOnly=computed(()=>!!form.value?.protected||!data.value?.can_manage);
const selectedCount=(g:any)=>g.permissions.filter((p:any)=>form.value?.permissions.includes(p.key)).length;
function togglePermission(key:string,checked:boolean){const next=new Set<string>(form.value.permissions);const group=data.value.catalog.find((g:any)=>g.permissions.some((p:any)=>p.key===key));if(checked){next.add(key);const view=group?.permissions.find((p:any)=>p.key.endsWith('.view'));if(view&&data.value.grantable.includes(view.key))next.add(view.key);}else{next.delete(key);if(key.endsWith('.view'))group.permissions.forEach((p:any)=>next.delete(p.key));}form.value.permissions=[...next];}
async function load(){try{const r=await fetch('/accounting/api/roles',{headers:{Accept:'application/json'}});const d=await r.json();if(!r.ok)throw Error(d.message);data.value=d;if(props.openId){const role=d.roles?.find((role:any)=>role.id===props.openId);if(role)open(role);}}catch(e){error.value=(e as Error).message;}}
function open(role?:any,copy=false){error.value='';form.value=role?{...role,id:copy?undefined:role.id,name:copy?role.name+' copy':role.name,permissions:[...role.permissions],protected:copy?false:role.protected}:{name:'',description:'',active:true,permissions:[]};}
async function save(){if(busy.value)return;busy.value=true;error.value='';try{const r=await fetch('/accounting/api/roles',{method:'POST',headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':props.csrf||''},body:JSON.stringify(form.value)});const d=await r.json();if(!r.ok)throw Error(Object.values(d.errors||{}).flat().join(' ')||d.message);form.value=null;emit('notice',d.message);await load();emit('changed');}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
onMounted(load);
</script>
<template><section><div class="ac-section-heading"><div><h2>Roles and permissions</h2><p class="muted">Define Accounting responsibilities here. Assign these roles to employees and invitations in Administration.</p></div><button v-if="data?.can_manage" class="button primary" @click="open()">+ Create role</button></div><p v-if="error&&!form" role="alert" class="notice admin-error">{{error}}</p><input v-model="search" type="search" placeholder="Find a role" aria-label="Find Accounting role"><div v-if="data" class="ac-role-grid"><article v-for="role in data.roles.filter((r:any)=>r.name.toLowerCase().includes(search.toLowerCase()))" :key="role.id" class="ac-books-panel"><span class="ac-badge" :class="role.active?'active':'inactive'">{{role.active?'Active':'Inactive'}}</span><h3>{{role.name}}</h3><p class="muted">{{role.description||'Accounting access and responsibilities.'}}</p><p>{{role.permissions.length}} permissions · {{role.assigned_users}} assigned users</p><div class="ac-voucher-actions"><button class="button" @click="open(role)">{{!role.protected&&data.can_manage?'Edit role':'View permissions'}}</button><button v-if="data.can_manage" class="button" @click="open(role,true)">Copy role</button></div><small v-if="role.protected" class="muted">Built-in template — copy to customise.</small></article></div>
<AdminDialog v-if="form" :title="form.protected?'Role permissions':form.id?'Edit role':'Create role'" :busy="busy" dialog-class="ac-dialog ac-review-dialog ac-role-classic" @close="!busy&&(form=null)">
<form @submit.prevent="save"><p v-if="error" class="notice admin-error" role="alert">{{error}}</p>
<fieldset class="ac-journal-fields" :disabled="busy||readOnly"><div class="ac-form-grid ac-role-classic-details"><label>Role name<input v-model="form.name" required maxlength="100" placeholder="e.g. Finance Officer"></label><label class="ac-check ac-role-classic-active"><input v-model="form.active" type="checkbox">Active role</label><label class="ac-role-classic-description">Description <span class="muted">(optional)</span><textarea v-model="form.description" maxlength="2000" rows="2" placeholder="Describe this role's responsibilities"></textarea></label></div>
<div class="ac-role-classic-heading"><h3>Permissions</h3><span>{{form.permissions.length}} selected</span></div>
<div class="ac-permission-groups"><section v-for="group in data.catalog" :key="group.key"><header><h3>{{group.name}}</h3><small>{{selectedCount(group)}} / {{group.permissions.length}}</small></header><div><label v-for="permission in group.permissions" :key="permission.key" class="ac-check" :class="{selected:form.permissions.includes(permission.key)}"><input type="checkbox" :aria-label="permission.name" :checked="form.permissions.includes(permission.key)" :disabled="!data.grantable.includes(permission.key)" @change="togglePermission(permission.key,($event.target as HTMLInputElement).checked)">{{permission.name}}</label></div></section></div></fieldset>
<p class="ac-help">{{form.protected?'Built-in template. Copy this role to customise its permissions.':'View access is selected automatically when required. Posting permissions follow the approval workflow.'}}</p>
<div class="ac-form-actions"><button type="button" class="button" :disabled="busy" @click="form=null">{{readOnly?'Close':'Cancel'}}</button><button v-if="!readOnly" class="button primary" :disabled="busy">{{busy?'Saving...':'Save role'}}</button></div></form></AdminDialog></section></template>
